.note-to-mp {box-sizing:border-box;max-width:640px;margin:0 auto;padding:18px 20px 40px;background:#FFFFFF;color:#30383D;font-family:'Songti SC',STSong,SimSun,serif;font-size:16px;line-height:1.9!important;word-break:break-word;overflow-wrap:break-word;}
.note-to-mp * {box-sizing:border-box;}
.note-to-mp p {margin:0 0 22px!important;font-size:16px;line-height:1.9!important;letter-spacing:.03em;text-align:justify!important;}
.note-to-mp h1 {margin:0 0 28px;font-size:24px;font-weight:700;line-height:1.5!important;word-break:break-word;}
.note-to-mp h2 {margin:44px 0 22px!important;font-size:20px;font-weight:700;line-height:1.5!important;}
.note-to-mp h3 {margin:28px 0 16px!important;font-size:17px;font-weight:700;line-height:1.55!important;}
.note-to-mp h4,.note-to-mp h5,.note-to-mp h6 {margin:24px 0 12px!important;font-size:16px;font-weight:700;line-height:1.55!important;}
.note-to-mp strong {font-weight:700;}
.note-to-mp em {font-style:italic;}
.note-to-mp a {text-decoration:none;border-bottom:1px solid currentColor;}
.note-to-mp blockquote {margin:28px 0!important;padding:20px;}
.note-to-mp blockquote p {margin:0!important;font-size:15px;line-height:1.85!important;text-align:inherit!important;}
.note-to-mp ul,.note-to-mp ol {margin:0 0 24px;padding:0 0 0 25px;line-height:1.85!important;}
.note-to-mp li {margin:10px 0;padding-left:3px;font-size:16px;line-height:1.85!important;}
.note-to-mp code {padding:2px 5px;border-radius:3px;background:#F1F4F5;color:#34474F;font-family:Menlo,Monaco,Consolas,monospace;font-size:14px;white-space:normal;overflow-wrap:anywhere;}
.note-to-mp .code-section {margin:24px 0;overflow:hidden;border:1px solid #DFE5E8;background:#F6F8F9;border-radius:4px;}
.note-to-mp .code-section pre {margin:0;padding:16px;white-space:pre-wrap!important;word-break:break-all!important;}
.note-to-mp .code-section code {display:block;padding:0;background:transparent;border:none;font-size:13px;line-height:1.7!important;}
.note-to-mp img {display:block;width:100%;max-width:100%;height:auto;margin:28px auto;border:0;}
.note-to-mp hr {height:0;border:0;border-top:1px solid #DFE5E8;margin:40px 0;}
.note-to-mp table {width:100%;table-layout:fixed;box-sizing:border-box;margin:24px 0;border-collapse:collapse;border-spacing:0;font-family:'Songti SC',STSong,SimSun,serif;font-size:13px;line-height:1.7!important;}
.note-to-mp th,.note-to-mp td {box-sizing:border-box;padding:10px 9px;text-align:left;vertical-align:top;white-space:normal;word-break:break-word;overflow-wrap:anywhere;border-bottom:1px solid #E1E5E7;}
.note-to-mp th {font-weight:700;}

.note-to-mp {max-width:610px;padding:30px 25px 48px;color:#303C42;font-size:17px;line-height:1.94!important;}
.note-to-mp p {font-size:17px;line-height:1.94!important;letter-spacing:.025em;margin-bottom:24px!important;}
.note-to-mp > p {text-indent:2em;}
.note-to-mp h1 {text-align:left;font-size:24px;font-weight:600;line-height:1.6!important;letter-spacing:.055em;padding:0 0 22px;margin-bottom:30px;border-bottom:5px solid #D6ECF0;color:#303C42;}
.note-to-mp h1 + p {text-indent:0;color:#486570;}
.note-to-mp h2 {text-align:left;margin:48px 0 24px!important;padding:0;font-size:21px;font-weight:600;letter-spacing:.08em;color:#303C42;}
.note-to-mp h3 {margin:30px 0 18px!important;font-weight:500;font-size:18px;color:#486570;}
.note-to-mp h4,.note-to-mp h5,.note-to-mp h6 {color:#486570;font-weight:600;}
.note-to-mp strong {color:#303C42;text-decoration:underline;text-decoration-color:#ADC9D0;text-decoration-thickness:1px;text-underline-offset:4px;}
.note-to-mp em,.note-to-mp a {color:#815750;}
.note-to-mp blockquote {margin:34px 19px 36px!important;padding:12px 0;background:#FFFFFF;color:#815750;text-align:left;border:0;}
.note-to-mp blockquote p {text-indent:0;font-size:19px;font-weight:500;line-height:1.95!important;letter-spacing:.04em;}
.note-to-mp ul {list-style-type:circle;padding-left:25px;}
.note-to-mp ol {list-style-type:lower-roman;padding-left:31px;}
.note-to-mp li {margin:15px 0;font-size:16px;line-height:1.95!important;}
.note-to-mp li::marker {color:#815750;}
.note-to-mp img {padding:5px;border:1px solid #DFE7E9;background:#FFFFFF;border-radius:0;margin:32px auto;}
.note-to-mp hr {width:28%;margin:44px 0;border-top:1px solid #ADC9D0;}
.note-to-mp code {background:#F5F8F9;color:#486570;border-radius:0;}
.note-to-mp .code-section {border:0;border-top:1px solid #DFE7E9;border-bottom:1px solid #DFE7E9;border-radius:0;background:#FAFCFD;}
.note-to-mp .code-section code {color:#303C42;}
.note-to-mp th {background:#FFFFFF;color:#486570;border-top:1px solid #ADC9D0;border-bottom:1px solid #ADC9D0;font-weight:600;}
.note-to-mp td {background:#FFFFFF;color:#303C42;border-color:#DFE7E9;}
